readonly myPlugins: ThfPlugins = defaultPlugins => {
  const customPlugin = new ThfRichTextPlugin({
    props: {
      handleKeyDown: (_view, event) => {
        if (event.key === 'F2') {
          // Executa uma regra customizada.
          return true;
        }

        return false;
      }
    }
  });

  return [...defaultPlugins, customPlugin];
};
